package com.tracksphere.domain.model; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="sos_alerts") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class SosAlert { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; private Double latitude; private Double longitude; @Column(length=500) private String message; @Column(nullable=false,length=30) private String status="OPEN"; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="resolved_at") private Instant resolvedAt; public SosAlert(User user,Double latitude,Double longitude,String message){id=UUID.randomUUID();this.user=user;this.latitude=latitude;this.longitude=longitude;this.message=message;createdAt=Instant.now();} public void resolve(){status="RESOLVED";resolvedAt=Instant.now();} }
